#!/usr/bin/env python3

import warnings
# Silence the LibreSSL warning generated by urllib3
warnings.filterwarnings("ignore", message=".*supports OpenSSL 1.1.1+.*")

import os
import sys
import json
import asyncio
import shutil
import requests
import time
from playsound import playsound

# --- CORE PATH CONFIGURATION ---
BASE_STORAGE_DIR = os.path.expanduser("~/.aiim")
DB_DIR = os.path.join(BASE_STORAGE_DIR, "knowledge_base")
HISTORY_FILE = os.path.join(BASE_STORAGE_DIR, ".chat_history.json")
SFX_DIR = os.path.join(BASE_STORAGE_DIR, "sfx")
SFX_OPEN = os.path.join(SFX_DIR, "mixkit-creaky-door-open-195.wav")
SFX_EXIT = os.path.join(SFX_DIR, "mixkit-creaky-closing-wood-door-189.wav")
SFX_SEND = os.path.join(SFX_DIR, "mixkit-software-interface-start-2574.wav")
SFX_RECV = os.path.join(SFX_DIR, "mixkit-software-interface-back-2575.wav")
SFX_ALT1 = os.path.join(SFX_DIR, "mixkit-retro-game-notification-212.wav")
SFX_ALT2 = os.path.join(SFX_DIR, "mixkit-computer-digital-lock-2859.wav")
SFX_ALT3 = os.path.join(SFX_DIR, "mixkit-alert-bells-echo-765.wav")
SFX_ERR1 = os.path.join(SFX_DIR, "mixkit-police-short-whistle-615.wav")
EMBEDDING_MODEL = "nomic-embed-text"
LLM_MODEL = "llama3.1"

os.makedirs(BASE_STORAGE_DIR, exist_ok=True)

# --- DATA PROCESSING LOGIC ---

def process_and_add_docs(documents, progress_callback):
    """Slices documents and appends vectors with live status updates."""
    if not documents:
        try:
            playsound(SFX_ALT3, block=False)
        except Exception:
            pass
        return "⚠️  No valid textual data found to process."

    from langchain_text_splitters import RecursiveCharacterTextSplitter
    from langchain_ollama import OllamaEmbeddings
    from langchain_community.vectorstores import Chroma

    progress_callback("Analyzing & splitting document layout...", 25)
    text_splitter = RecursiveCharacterTextSplitter(chunk_size=1200, chunk_overlap=300)
    final_chunks = text_splitter.split_documents(documents)
    total_chunks = len(final_chunks)

    progress_callback(f"Vectorizing {total_chunks} blocks locally...", 60)
    embeddings = OllamaEmbeddings(model=EMBEDDING_MODEL)

    # -- Commit files to disk database --
    # Process in chunks of 5-10 items to prevent Ollama socket flood
    batch_size = 15

    # Initialize the database with the first batch
    db = Chroma.from_documents(
        documents=final_chunks[:batch_size],
        embedding=embeddings,
        persist_directory=DB_DIR
    )

    # Add remaining chunks with a time sleep interval
    for i in range(batch_size, total_chunks, batch_size):
        batch = final_chunks[i:i + batch_size]
        db.add_documents(documents=batch)

        # Adjust progress metric dynamically
        current_pct = int(60 + (i / total_chunks) * 35)
        progress_callback(f"Indexing vectors ({i}/{total_chunks})...", current_pct)

        time.sleep(0.5) # Sleep half a second between small batches

    progress_callback("Commit complete!", 100)
    try:
        playsound(SFX_ALT1, block=False)
    except Exception:
        pass
    return f"✅  Database successfully updated with {total_chunks} data blocks."


# --- REUSABLE CORE EXTRACTION HELPERS ---

def extract_site_content(url):
    """Core logic to fetch and strip text from a website."""
    from bs4 import BeautifulSoup
    from langchain_core.documents import Document

    headers = {'User-Agent': 'Mozilla/5.0'}
    res = requests.get(url, headers=headers, timeout=10)
    soup = BeautifulSoup(res.text, 'html.parser')

    for el in soup(["script", "style", "nav", "footer", "header"]):
        el.extract()

    text = soup.get_text(separator=" ")
    return [Document(page_content=text, metadata={"source": url, "category": "web"})]


def extract_file_content(file_path):
    """Core logic to parse text from an individual local file."""
    from langchain_community.document_loaders import PyPDFLoader, TextLoader

    expanded = os.path.expanduser(file_path)
    if not os.path.isfile(expanded):
        raise FileNotFoundError(f"File not found: {expanded}")

    # Use os.path.basename(expanded) if you only want the file name instead of full path
    if expanded.endswith('.pdf'):
        docs = PyPDFLoader(expanded).load()
    elif expanded.endswith('.txt'):
        docs = TextLoader(expanded).load()
    else:
        raise ValueError("Unsupported file format. Please choose a .pdf or .txt file.")

    # Standardize source metadata to just the filename (optional)
    for doc in docs:
        doc.metadata["source"] = os.path.basename(expanded)
    return docs


# --- MAIN INGESTION ENTRYPOINTS ---

def run_site_scrape(url, progress_callback):
    """Scrapes clean text contents directly from a live public website."""
    progress_callback("Establishing secure web connection...", 15)
    try:
        docs = extract_site_content(url)
        return process_and_add_docs(docs, progress_callback)
    except Exception as e:
        try:
            playsound(SFX_ERR1, block=False)
        except Exception:
            pass
        return f"❌ Web extraction failed: {str(e)[:40]}"


def run_single_file_ingest(file_path, progress_callback):
    """Parses an individual standalone data file from any disk path."""
    progress_callback("Extracting isolated file streams...", 30)
    try:
        docs = extract_file_content(file_path)
        return process_and_add_docs(docs, progress_callback)
    except Exception as e:
        try:
            playsound(SFX_ERR1, block=False)
        except Exception:
            pass
        return f"❌ Error: {str(e)[:50]}"


def run_manifest_ingest(manifest_path, progress_callback):
    """Reads a manifest file and processes each line using refactored extraction streams."""
    expanded_manifest = os.path.expanduser(manifest_path)
    if not os.path.isfile(expanded_manifest):
        try:
            playsound(SFX_ERR1, block=False)
        except Exception:
            pass
        return "❌ Error: The manifest file path provided does not exist."

    progress_callback("Reading manifest contents...", 10)
    try:
        with open(expanded_manifest, 'r', encoding='utf-8') as f:
            lines = [line.strip() for line in f if line.strip() and not line.strip().startswith('#')]
    except Exception as e:
        try:
            playsound(SFX_ERR1, block=False)
        except Exception:
            pass
        return f"❌ Error reading manifest file: {str(e)[:40]}"

    if not lines:
        try:
            playsound(SFX_ALT3, block=False)
        except Exception:
            pass
        return "⚠️ The manifest file is empty or contains no valid targets."

    all_docs = []
    total_items = len(lines)

    for idx, item in enumerate(lines):
        progress_callback(f"Processing ({idx+1}/{total_items}): {item[:20]}...", int(10 + (idx / total_items) * 50))

        try:
            # Reuses exact web scraping helper logic
            if item.startswith(('http://', 'https://')):
                all_docs.extend(extract_site_content(item))
            # Reuses exact file parsing helper logic
            else:
                all_docs.extend(extract_file_content(item))
        except Exception as e:
            # Log error quietly to terminal standard error and keep going through the manifest
            print(f"Skipping '{item[:30]}' due to extraction failure: {e}", file=sys.stderr)

        # give Ollama some breathing room between processing requests
        time.sleep(2)

    # Single batch compile step for performance stability
    return process_and_add_docs(all_docs, progress_callback)


def query_local_ai(user_raw, chat_history):
    """Performs an offline RAG factual text query matching current context loops."""
    import ollama
    context_str = ""

    if os.path.exists(DB_DIR):
        try:
            from langchain_community.vectorstores import Chroma
            from langchain_ollama import OllamaEmbeddings
            vs = Chroma(persist_directory=DB_DIR, embedding_function=OllamaEmbeddings(model=EMBEDDING_MODEL))

            # Increase k to 4 or 5 for better answer coverage
            #relevant = vs.as_retriever(search_kwargs={"k": 3}).invoke(user_raw)

            # Use Similarity Score Thresholding
            relevant = vs.as_retriever(
                search_type="similarity_score_threshold",
                search_kwargs={"score_threshold": 0.7, "k": 10}
            ).invoke(user_raw)

            # Formats context blocks uniquely numbered with their true source attached
            context_blocks = []
            for idx, doc in enumerate(relevant, start=1):
                source_name = doc.metadata.get("source", "Unknown Source")
                block_text = f"--- Document [{idx}] (Source: {source_name}) ---\n{doc.page_content}\n"
                context_blocks.append(block_text)

            context_str = "\n".join(context_blocks)
        except:
            pass

    system_instructions = (
        "You are an offline custom AI assistant running inside a blue AIM messenger app window.\n\n"
        "CONTEXT OBJECTIVE:\n"
        "Answer the user's question by thoroughly evaluating the provided Document Facts text blocks below. "
        "Provide comprehensive, long, detailed, and analytical responses. Break down complex steps, "
        "explain the 'why' behind the facts, and structure your explanation using Markdown.\n\n"
        "STRICT CITATION RULES:\n"
        "1. For EVERY factual claim, quote, or inference you make, you MUST append the matching index number "
        "as an inline footnote anchor immediately following the sentence. Use the format, [1], [2], etc.\n"
        "2. Do not combine sentences under a single citation. Cite line-by-line if multiple sources are used.\n"
        "3. Do not invent facts completely detached from the text. If the answer absolutely cannot be inferred "
        "from the provided facts, state: 'I do not have enough information in the provided database.'\n\n"
        "FOOTNOTE FORMATTING RULES:\n"
        "At the very bottom of your response, add a blank line followed by a horizontal divider line (`---`).\n"
        "Sources:\n"
        "[1] filename.txt\n\n"
        f"Document Facts:\n{context_str}"
    )

    payload = [{"role": "system", "content": system_instructions}]
    payload.extend(chat_history[-10:])
    payload.append({"role": "user", "content": user_raw})

    full_reply = ""
    try:
        stream = ollama.chat(
            model=LLM_MODEL,
            messages=payload,
            stream=True,
            options={
                "num_predict": 1024,
                "temperature": 0.5,
                "top_p": 0.9
            }
        )
        for chunk in stream:
            full_reply += chunk['message']['content']
    except Exception as e:
        full_reply = f"[Ollama Connection Error: {e}]"

    return full_reply

from rich.text import Text
from rich.markdown import Markdown
from textual.app import App, ComposeResult
from textual.containers import Container, Horizontal, Grid
from textual.screen import ModalScreen
from textual.widgets import Footer, Input, RichLog, Select, Label, Button

# --- SYSTEM MODAL POP-UPS FOR USER CAPTURE ---

class InputModal(ModalScreen[str]):
    """A floating pop-up window overlay to safely query paths and text metadata."""

    # Force Textual's layout compiler to recognize this child widget first
    AUTO_FOCUS = "#modal_input"

    CSS = """
    InputModal {
        align: center middle;
        background: rgba(0, 0, 0, 0.6);
    }
    #dialog_box {
        layout: vertical;
        padding: 1 2;
        width: 60;
        height: auto;
        background: #00aaaa;
        border: thick white;
        color: white;
    }
    #modal_lbl {
        text-align: center;
        text-style: bold;
        margin-bottom: 1;
        width: 100%;
        height: auto;
    }
    #modal_input {
        background: black;
        color: white;
        border: tall white;
        width: 100%;
        height: 3;
        margin-bottom: 1;
    }
    #modal_input:focus {
        border: tall cyan;
    }
    #btn_row {
        layout: horizontal;
        align: center middle;
        height: 3;
        width: 100%;
    }
    .modal_btn {
        margin: 0 1;
    }
    """

    def __init__(self, prompt_text: str):
        super().__init__()
        self.prompt_text = prompt_text

    def compose(self) -> ComposeResult:
        yield Grid(
            Label(self.prompt_text, id="modal_lbl"),
            Input(placeholder="Type value here...", id="modal_input"),
            Horizontal(
                Button("Submit", variant="success", id="submit_btn", classes="modal_btn"),
                Button("Cancel", variant="error", id="cancel_btn", classes="modal_btn"),
                id="btn_row"
            ),
            id="dialog_box"
        )

    def on_screen_activated(self) -> None:
        """
        Fired by Textual the exact hardware microsecond this modal becomes
        the active layer. Forcibly overrides any focus commands
        sent by parent dropdown widgets.
        """
        input_widget = self.query_one("#modal_input")
        input_widget.focus()
        # Enforce selection state to verify that the blinking cursor is active
        input_widget.select_all()

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "submit_btn":
            user_val = self.query_one("#modal_input").value.strip()
            self.dismiss(user_val)
        else:
            self.dismiss("")

    def on_input_submitted(self, event: Input.Submitted) -> None:
        event.stop()
        self.dismiss(event.value.strip())


# --- THE MAIN CHAT INTERFACE ---

class AIMAssistantApp(App):
    """A fully responsive, interactive AIM-styled console layout wrapper."""

    CSS = """
    Screen {
        background: #0000aa;
    }
    #main_container {
        layout: vertical;
        padding: 1 2;
    }
    #top_bar {
        layout: horizontal;
        height: 3;
        background: #00aaaa;
        color: white;
        margin-bottom: 1;
        content-align: center middle;
    }
    #menu_lbl {
        color: yellow;
        padding: 0 1;
        text-style: bold;
    }
    #action_menu {
        width: 45;
    }
    #chat_log {
        background: white;
        color: black;
        border: solid blue;
        height: 1fr;
        margin-bottom: 1;

        /* The idle background track and handle color */
        scrollbar-background: #363636;
        scrollbar-color: #808080;

        /* The background track color when hovered or clicked */
        scrollbar-background-hover: #808080;
        scrollbar-background-active: #363636;

        /* The moving thumb handle color when hovered or clicked */
        scrollbar-color-hover: #ffffff;
        scrollbar-color-active: #808080;
    }
    #input_box {
        background: white;
        color: black;
        border: solid blue;
        height: 3;
    }
    #status_row {
        height: 1;
        color: #00ff00;
        text-style: bold;
    }

    /* Explicitly strip unnecessary border rules on the dropdown overlay */
    SelectOverlay {
        border: none;
    }

    /* Ensure the underlying container list clears stacked dividers */
    SelectOverlay > OptionList {
        border: solid blue;
        background: white;
    }

    /* Clear specific sub-widget border focus traps */
    SelectCurrent, SelectCurrent:focus {
        border: none;
    }
    """

    BINDINGS = [("escape", "quit", "Exit Messenger")]

    def compose(self) -> ComposeResult:
        menu_options = [
            ("+ Action Menu ...", "none"),
            ("=> Ingest Manifest File", "ingest_manifest"),
            ("=> Scrape Public Website", "scrape_site"),
            ("=> Ingest Individual File", "ingest_file"),
            ("=> Reset Session Memory", "wipe_mem"),
            ("=> Wipe DB", "wipe_db"),
            ("=> Reset Session Memory & Wipe DB", "wipe_all")
        ]

        yield Container(
            Horizontal(
                Label(" 💾  AI IM (AIIM) CLIENT v1.1 ", id="menu_lbl"),
                Select(menu_options, value="none", id="action_menu", allow_blank=False),
                id="top_bar"
            ),
            RichLog(id="chat_log", max_lines=1000, wrap=True),
            Label(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"), id="status_row"),
            Input(placeholder="💬 Type your message here and hit Enter...", id="input_box"),
            id="main_container"
        )
        yield Footer()

    def on_mount(self) -> None:
        self.chat_log = self.query_one("#chat_log")
        self.status = self.query_one("#status_row")
        self.chat_history = []

        try:
            playsound(SFX_OPEN, block=False)
        except Exception as e:
            self.chat_log.write(f"⚠️  Audio Debug Error: {e}")

        if os.path.exists(HISTORY_FILE):
            try:
                with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                    self.chat_history = json.load(f)
            except: pass

        self.chat_log.write(Text.from_markup("🔒 [bold #0b6623]SYSTEM:[/bold #0b6623] Secure Local Connection Established."))
        if self.chat_history:
            self.chat_log.write(Text.from_markup(f"⚙️  [bold #daa520]Found existing chat history logs ({len(self.chat_history)//2} messages preserved).[/bold #daa520]"))
        self.chat_log.write("👉 Choose a dropdown menu function above to index data or begin typing below to chat.")

    def exit(self, result = None) -> None:
        try:
            playsound(SFX_EXIT, block=True)
        except Exception:
            pass

        super().exit(result)

    def update_live_progress(self, task_msg: str, completion_percentage: int) -> None:
        """Draws a live progress meter directly into the application layout."""
        bar_width = 20
        filled = int(bar_width * completion_percentage // 100)
        meter = "█" * filled + "░" * (bar_width - filled)
        self.status.update("")
        self.status.update(Text.from_markup(f"[#222021 on #d9dddc]🏃 {task_msg} [{meter}] {completion_percentage}%[/]"))

    async def on_input_submitted(self, event: Input.Submitted) -> None:
        user_text = event.value.strip()
        if not user_text:
            return

        event.input.value = ""
        if user_text.lower() == 'exit':
            self.exit()
            return

        self.chat_log.write(Text.from_markup(f"\n[bold #0000ff]You:[/bold #0000ff] {user_text}"))
        try:
            playsound(SFX_SEND, block=False)
        except Exception:
            pass
        self.status.update(Text.from_markup("[#222021 on #d9dddc]🤖 AI Assistant is typing...[/]"))

        worker = self.run_worker(lambda: query_local_ai(user_text, self.chat_history), thread=True)

        async def handle_response():
            reply = await worker.wait()
            self.chat_log.write(Text.from_markup("[bold #ff0000]AI Assistant:[/bold #ff0000]"))
            self.chat_log.write(Markdown(reply))
            try:
                playsound(SFX_RECV, block=False)
            except Exception:
                pass
            self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

            self.chat_history.append({"role": "user", "content": user_text})
            self.chat_history.append({"role": "assistant", "content": reply})
            with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
                json.dump(self.chat_history, f, ensure_ascii=False, indent=2)

        asyncio.create_task(handle_response())

    def on_screen_resume(self) -> None:
        """
        Intercepts Textual's automatic focus restoration engine.
        If a modal overlay screen is active, force keyboard priority
        straight into its input box, breaking the dropdown list focus trap.
        """
        # Check if the active, top-most visible layer on our terminal is our Modal Screen
        if isinstance(self.screen, InputModal):
            try:
                # Target the inner input box directly inside the modal and capture focus
                self.screen.query_one("#modal_input").focus()
            except Exception:
                pass

    def on_select_changed(self, event: Select.Changed) -> None:
        selection = str(event.value)
        if selection == "none":
            return

        # 1. Reset dropdown menu state
        self.query_one("#action_menu").value = "none"

        # 2. We call call_after_refresh to wait
        # exactly one screen render tick. This allows the dropdown list menu to
        # completely collapse and naturally drop its event lock BEFORE the modal loads.
        self.call_after_refresh(self.launch_modal_thread, selection)

    def launch_modal_thread(self, selection: str) -> None:
        """Triggers the async background routing loop cleanly inside a worker."""
        self.run_worker(self.handle_menu_navigation(selection))

    async def handle_menu_navigation(self, choice: str) -> None:
        """Handles triggering modals and offloading background execution threads safely."""

        if choice == "ingest_manifest":
            path_val = await self.push_screen_wait(InputModal("Enter absolute path to the manifest file (.txt):"))
            if path_val:
                self.chat_log.write(f"\n⚙️  SYSTEM: Commencing manifest file processing at '{path_val}'...")
                worker = self.run_worker(lambda: run_manifest_ingest(path_val, self.update_live_progress), thread=True)
                res = await worker.wait()
                self.chat_log.write(f"⚙️  SYSTEM: {res}")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "scrape_site":
            url_val = await self.push_screen_wait(InputModal("Enter target URL to crawl & extract text values:"))
            if url_val:
                self.chat_log.write(f"\n⚙️  SYSTEM: Connecting to web resource '{url_val}'...")
                worker = self.run_worker(lambda: run_site_scrape(url_val, self.update_live_progress), thread=True)
                res = await worker.wait()
                self.chat_log.write(f"⚙️  SYSTEM: {res}")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "ingest_file":
            file_val = await self.push_screen_wait(InputModal("Enter structural location path to standalone .pdf or .txt file:"))
            if file_val:
                self.chat_log.write(f"\n⚙️  SYSTEM: Attempting context validation for '{file_val}'...")
                worker = self.run_worker(lambda: run_single_file_ingest(file_val, self.update_live_progress), thread=True)
                res = await worker.wait()
                self.chat_log.write(f"⚙️  SYSTEM: {res}")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "wipe_mem":
            confirm = await self.push_screen_wait(InputModal("Type 'WIPEMEM' to delete history files permanently:"))
            if confirm == "WIPEMEM":
                try:
                    playsound(SFX_ALT2, block=False)
                except Exception:
                    pass
                if os.path.exists(HISTORY_FILE): os.remove(HISTORY_FILE)
                self.chat_history = []
                self.chat_log.clear()
                self.chat_log.write("💥 Cleanup complete! Conversation memory logs reset to zero.")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "wipe_db":
            confirm = await self.push_screen_wait(InputModal("Type 'WIPEDB' to delete history files and data vectors permanently:"))
            if confirm == "WIPEDB":
                try:
                    playsound(SFX_ALT2, block=False)
                except Exception:
                    pass
                if os.path.exists(DB_DIR): shutil.rmtree(DB_DIR)
                self.chat_log.clear()
                self.chat_log.write("💥 Cleanup complete! Vector directories wiped.")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "wipe_all":
            confirm = await self.push_screen_wait(InputModal("Type 'WIPEALL' to delete history files and data vectors permanently:"))
            if confirm == "WIPEALL":
                try:
                    playsound(SFX_ALT2, block=False)
                except Exception:
                    pass
                if os.path.exists(HISTORY_FILE): os.remove(HISTORY_FILE)
                if os.path.exists(DB_DIR): shutil.rmtree(DB_DIR)
                self.chat_history = []
                self.chat_log.clear()
                self.chat_log.write("💥 Cleanup complete! Conversation memory logs and vector directories reset to zero.")
                self.status.update(Text.from_markup("[#222021 on #d9dddc]System Status: Online & Idle[/]"))

        elif choice == "exit":
            self.exit()

        # Safely return focus right back to the chat box when modals close
        self.query_one("#input_box").focus()

if __name__ == "__main__":
    app = AIMAssistantApp()
    app.run()
